-- interview-batch5-diagrams.sql — 面試題庫補圖 批次 5（bank 最後 6 題）
-- q18  tr = 0.8473 x Rp x Cb 的直線圖：2.2k -> 186ns PASS、10k -> 847ns FAIL
-- q20  ESD 模型 HBM vs CDM 五項對照（含 HBM 峰值 2kV/1.5k = 1.33A）
-- q21  去耦電容擺位：rail -> 10uF -> 100nF -> pin，三個接地 via
-- q23  差分對走線 對 vs 錯（正確側等長等距實測 skew = 0）
-- q24  MOSFET 六參數 + 兩條等 FOM 曲線
-- q25  Latch-up 寄生 PNPN 等效電路（含交叉耦合與紅色低阻抗路徑）
--
-- 驗證：瀏覽器重疊實測 = 0；語意/幾何斷言全過。
-- 其中 q18 的斷言抓到真 bug：tr 公式單位少除 1000（kohm x pF 已經是 ns），
--   修正前曲線與標點全部跑到畫布外，重疊檢查卻是乾淨的 — 只驗重疊不夠。
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。冪等，可重跑。

-- q18：tr-Rp 關係：為什麼加大 Rp 是錯的
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">I2C tr FAIL: which knob turns the wrong way</text><text x="10" y="46" fill="#b91c1c" font-size="11" font-weight="bold">answer: (C) raising Rp makes tr worse</text><text x="500" y="46" fill="#64748b" font-size="11" text-anchor="end">Cb = 100pF</text><line x1="70" y1="80" x2="70" y2="250" stroke="#94a3b8" stroke-width="1.4" stroke-linecap="round"/><line x1="70" y1="250" x2="500" y2="250" stroke="#94a3b8" stroke-width="1.4" stroke-linecap="round"/><polyline points="70,250 480.04,92.91058000000001" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="70" y1="203.65" x2="500" y2="203.65" stroke="#b91c1c" stroke-width="1.2" stroke-linecap="round"/><text x="496" y="197.65" fill="#b91c1c" font-size="11" text-anchor="end">300ns limit</text><line x1="230.59900000000002" y1="188.4733105" x2="153.57834909724494" y2="217.98050340395147" stroke="#15803d" stroke-width="2" stroke-linecap="round"/><polygon points="152.0,213.8 155.2,222.2 145.174,221.20027299999998" fill="#15803d" stroke="#15803d" stroke-width="1"/><line x1="145.174" y1="221.20027299999998" x2="403.29565090275514" y2="122.31191959604851" stroke="#b91c1c" stroke-width="2" stroke-linecap="round"/><polygon points="404.9,126.5 401.7,118.1 411.70000000000005,119.09215" fill="#b91c1c" stroke="#b91c1c" stroke-width="1"/><text x="150" y="246" fill="#15803d" font-size="11">(A) 4.7k -> 2.2k: tr drops under the limit</text><text x="240" y="96" fill="#b91c1c" font-size="11">(C) 2.2k -> 10k: tr blows past it</text><text x="500" y="268" fill="#64748b" font-size="11" text-anchor="end">Rp</text><text x="64" y="86" fill="#64748b" font-size="11" text-anchor="end">tr</text><text x="10" y="292" fill="#1d2943" font-size="11">tr = 0.8473 x Rp x Cb. A FAIL means tr is too big, so Rp or Cb must come down.</text><text x="10" y="312" fill="#64748b" font-size="11">(B) and (D) both shrink Cb - same formula, the other factor. Only (C) goes up.</text></svg></div>$vsq$ as box) n
 where question like $q$%tr (上升時間) FAIL%$q$;

-- q20：HBM vs CDM 五項對照
