"round"/><line x1="162" y1="110" x2="180" y2="110" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ic"><rect x="180" y="80" width="52" height="60" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="206" y="114" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">DUT</text><line x1="60" y1="132" x2="60" y2="156" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="60" y1="156" x2="60" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="48" y1="170" x2="72" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="52" y1="175" x2="68" y2="175" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="56" y1="180" x2="64" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="206" y1="140" x2="206" y2="156" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="206" y1="156" x2="206" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="194" y1="170" x2="218" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="198" y1="175" x2="214" y2="175" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="202" y1="180" x2="210" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="390" y="46" fill="#b45309" font-size="12" text-anchor="middle" font-weight="bold">CDM: the part itself is charged</text><g data-sym="ic"><rect x="304" y="80" width="52" height="60" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="330" y="114" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">DUT</text><line x1="356" y1="110" x2="400" y2="110" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="capacitor"><line x1="400" y1="110" x2="400" y2="127" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="389" y1="127" x2="411" y2="127" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="389" y1="137" x2="411" y2="137" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="400" y1="137" x2="400" y2="154" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="412" y="140" fill="#64748b" font-size="11">1-30pF</text><line x1="400" y1="154" x2="400" y2="156" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="400" y1="156" x2="400" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="388" y1="170" x2="412" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="392" y1="175" x2="408" y2="175" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="396" y1="180" x2="404" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="330" y1="140" x2="330" y2="156" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="330" y1="156" x2="330" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="318" y1="170" x2="342" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="322" y1="175" x2="338" y2="175" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="326" y1="180" x2="334" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="420" y="100" fill="#64748b" font-size="11">discharges</text><text x="420" y="116" fill="#64748b" font-size="11">through ~1 ohm</text><text x="190" y="210" fill="#b91c1c" font-size="11" font-weight="bold">HBM</text><text x="340" y="210" fill="#b45309" font-size="11" font-weight="bold">CDM</text><text x="10" y="232" fill="#64748b" font-size="11">discharge time</text><text x="190" y="232" fill="#1d2943" font-size="11">~150ns</text><text x="340" y="232" fill="#1d2943" font-size="11">~1ns  (much faster)</text><text x="10" y="254" fill="#64748b" font-size="11">typical class</text><text x="190" y="254" fill="#1d2943" font-size="11">2000V  (Class 2)</text><text x="340" y="254" fill="#1d2943" font-size="11">500V  (Class C4)</text><text x="10" y="276" fill="#64748b" font-size="11">what it kills</text><text x="190" y="276" fill="#1d2943" font-size="11">junction burn-out</text><text x="340" y="276" fill="#1d2943" font-size="11">gate oxide punch-through</text><text x="10" y="308" fill="#1d2943" font-size="11">HBM is slow and resistive; CDM dumps the package charge in about a nanosecond.</text><text x="10" y="328" fill="#64748b" font-size="11">Guard at the connector: TVS to the rails, guard rings, short traces, no long stubs.</text></svg></div>$vsq$ as box) n
 where question like $q$%什麼是 ESD%$q$;

-- q21：去耦電容擺位與 via
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Decoupling: what matters is the loop, not the capacitor</text><text x="135" y="46" fill="#15803d" font-size="12" text-anchor="middle" font-weight="bold">right at the pin</text><text x="395" y="46" fill="#b91c1c" font-size="12" text-anchor="middle" font-weight="bold">parked far away</text><line x1="266" y1="58" x2="266" y2="286" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><g data-sym="rail"><line x1="60" y1="66" x2="60" y2="78" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="52" y1="66" x2="68" y2="66" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="72" y="72" fill="#64748b" font-size="11">VDD plane</text><line x1="60" y1="78" x2="60" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="60" y1="100" x2="195" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="capacitor"><line x1="100" y1="118" x2="100" y2="135" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="89" y1="135" x2="111" y2="135" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="89" y1="145" x2="111" y2="145" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="100" y1="145" x2="100" y2="162" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="100" y1="100" x2="100" y2="118" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="100" y1="162" x2="100" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="100" cy="100" r="2.6" fill="#1f4fd1"/></g><g data-sym="ground"><line x1="100" y1="180" x2="100" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="88" y1="194" x2="112" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="92" y1="199" x2="108" y2="199" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="96" y1="204" x2="104" y2="204" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="88" y="144" fill="#64748b" font-size="11" text-anchor="end">10u</text><g data-sym="capacitor"><line x1="170" y1="118" x2="170" y2="135" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="159" y1="135" x2="181" y2="135" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="159" y1="145" x2="181" y2="145" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="170" y1="145" x2="170" y2="162" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="170" y1="100" x2="170" y2="118" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="170" y1="162" x2="170" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="170" cy="100" r="2.6" fill="#1f4fd1"/></g><g data-sym="ground"><line x1="170" y1="180" x2="170" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="158" y1="194" x2="182" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="162" y1="199" x2="178" y2="199" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="166" y1="204" x2="174" y2="204" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="158" y="144" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">100n</text><g data-sym="ic"><rect x="195" y="78" width="50" height="44" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="220" y="104" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">IC</text><text x="100" y="222" fill="#64748b" font-size="11" text-anchor="middle">short fat via</text><g data-sym="rail"><line x1="320" y1="66" x2="320" y2="78" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="312" y1="66" x2="328" y2="66" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="332" y="72" fill="#64748b" font-size="11">VDD plane</text><line x1="320" y1="78" x2="320" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="320" y1="100" x2="455" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="350" cy="100" r="2.6" fill="#1f4fd1"/></g><line x1="350" y1="100" x2="350" y2="168" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="capacitor"><line x1="350" y1="168" x2="350" y2="185" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="339" y1="185" x2="361" y2="185" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="339" y1="195" x2="361" y2="195" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="350" y1="195" x2="350" y2="212" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="350" y1="212" x2="350" y2="226" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="350" y1="226" x2="350" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="338" y1="240" x2="362" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="342" y1="245" x2="358" y2="245" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="346" y1="250" x2="354" y2="250" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="362" y="150" fill="#b91c1c" font-size="11">long stub</text><text x="362" y="166" fill="#b91c1c" font-size="11">adds ESL</text><g data-sym="ic"><rect x="455" y="78" width="50" height="44" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="480" y="104" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">IC</text><text x="368" y="120" fill="#b91c1c" font-size="11">too far to help</text><text x="10" y="306" fill="#1d2943" font-size="11">100n hugs the pin, 10u sits behind it: plane -> bulk -> ceramic -> pin, never a T-stub.</text><text x="10" y="326" fill="#64748b" font-size="11">One cap per power pin, ground via short and fat - the loop area is the real inductance.</text></svg></div>$vsq$ as box) n
 where question like $q$%Bypass Capacitor（旁路電容）和%$q$;

-- q23：差分對走線 對 vs 錯
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Differential pair: what actually keeps the impedance</text><text x="10" y="46" fill="#15803d" font-size="11" font-weight="bold">answer: (C) matched length, fixed gap</text><line x1="258" y1="60" x2="258" y2="250" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><rect x="20" y="92" width="230" height="120" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><text x="135" y="108" fill="#64748b" font-size="11" text-anchor="middle">continuous reference plane</text><polyline points="30,140 90,140 130,180 240,180" fill="none" stroke="#15803d" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><polyline points="30,156 83.4,156 123.4,196 240,196" fill="none" stroke="#15803d" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="135" y="232" fill="#15803d" font-size="11" text-anchor="middle">same layer, matched length, fixed gap</text><rect x="270" y="92" width="105" height="120" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><rect x="395" y="92" width="105" height="120" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><text x="385" y="84" fill="#b91c1c" font-size="11" text-anchor="middle">crossing a split or changing layers</text><polyline points="280,140 490,140" fill="none" stroke="#b91c1c" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><polyline points="280,156 490,156" fill="none" stroke="#b91c1c" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><g data-sym="junction"><circle cx="430" cy="196" r="2.6" fill="#1f4fd1"/></g><g data-sym="junction"><circle cx="452" cy="196" r="2.6" fill="#1f4fd1"/></g><text x="441" y="228" fill="#b91c1c" font-size="11" text-anchor="middle">vias to another layer</text><text x="10" y="286" fill="#1d2943" font-size="11">(C) equal length kills skew and a fixed gap keeps the coupling, so Zdiff stays put.</text><text x="10" y="306" fill="#64748b" font-size="11">(A) and (D) both break the reference: split layers or no plane means no controlled Z0.</text><text x="10" y="326" fill="#64748b" font-size="11">(B) is a myth - what matters is the plane underneath, not the copper beside the pair.</text></svg></div>$vsq$ as box) n
 where question like $q$%PCB 設計中，高速差分對走線%$q$;

-- q24：六參數 + FOM 權衡曲線
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Picking a MOSFET: six numbers and one trade-off</text><text x="10" y="76" fill="#1d2943" font-size="11" font-weight="bold">V(BR)DSS</text><text x="96" y="76" fill="#64748b" font-size="11">breakdown, >= 1.2 x Vmax</text><text x="10" y="102" fill="#1d2943" font-size="11" font-weight="bold">RDS(on)</text><text x="96" y="102" fill="#64748b" font-size="11">conduction loss = I^2 x R</text><text x="10" y="128" fill="#1d2943" font-size="11" font-weight="bold">Qg</text><text x="96" y="128" fill="#64748b" font-size="11">gate charge -> switching loss</text><text x="10" y="154" fill="#1d2943" font-size="11" font-weight="bold">VGS(th)</text><text x="96" y="154" fill="#64748b" font-size="11">threshold the driver must clear</text><text x="10" y="180" fill="#1d2943" font-size="11" font-weight="bold">ID(max)</text><text x="96" y="180" fill="#64748b" font-size="11">continuous drain current</text><text x="10" y="206" fill="#1d2943" font-size="11" font-weight="bold">SOA</text><text x="96" y="206" fill="#64748b" font-size="11">safe V x I x time envelope</text><line x1="300" y1="80" x2="300" y2="250" stroke="#94a3b8" stroke-width="1.4" stroke-linecap="round"/><line x1="300" y1="250" x2="510" y2="250" stroke="#94a3b8" stroke-width="1.4" stroke-linecap="round"/><polyline points="330.0,116.7 335.0,135.7 340.0,150.0 345.0,161.1 350.0,170.0 355.0,177.3 360.0,183.3 365.0,188.5 370.0,192.9 375.0,196.7 380.0,200.0 385.0,202.9 390.0,205.6 395.0,207.9 400.0,210.0 405.0,211.9 410.0,213.6 415.0,215.2 420.0,216.7 425.0,218.0 430.0,219.2 435.0,220.4 440.0,221.4 445.0,222.4 450.0,223.3 455.0,224.2 460.0,225.0 465.0,225.8 470.0,226.5 475.0,227.1 480.0,227.8 485.0,228.4 490.0,228.9 495.0,229.5 500.0,230.0" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><g data-sym="junction"><circle cx="350" cy="170" r="2.6" fill="#1f4fd1"/></g><g data-sym="junction"><circle cx="425" cy="218" r="2.6" fill="#1f4fd1"/></g><text x="358" y="164" fill="#15803d" font-size="11">low RDS(on)</text><text x="433" y="212" fill="#15803d" font-size="11">low Qg</text><text x="300" y="66" fill="#1d2943" font-size="11" font-weight="bold">FOM = RDS(on) x Qg</text><text x="510" y="268" fill="#64748b" font-size="11" text-anchor="end">Qg</text><text x="294" y="86" fill="#64748b" font-size="11" text-anchor="end">RDS(on)</text><text x="10" y="292" fill="#1d2943" font-size="11">FOM = RDS(on) x Qg, and smaller is better: it prices conduction against switching.</text><text x="10" y="312" fill="#64748b" font-size="11">Low frequency and big current -> chase RDS(on). Fast switching -> chase Qg.</text></svg></div>$vsq$ as box) n
 where question like $q$%MOSFET 選型時需要關注%$q$;

-- q25：寄生 SCR 等效電路
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="360" viewBox="0 0 520 360" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="360" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Latch-up: the parasitic PNPN nobody drew</text><line x1="268" y1="60" x2="268" y2="300" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><g data-sym="rail"><line x1="200" y1="74" x2="200" y2="86" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="192" y1="74" x2="208" y2="74" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="212" y="80" fill="#b91c1c" font-size="11" font-weight="bold">VDD</text><line x1="60" y1="86" x2="200" y2="86" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="60" y1="92" x2="60" y2="104" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="60,104 53,107 67,113 53,119 67,125 60,128" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="60" y1="128" x2="60" y2="140" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="60" y1="86" x2="60" y2="92" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="60" y1="140" x2="60" y2="154" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="60" y1="154" x2="94" y2="154" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="48" y="112" fill="#64748b" font-size="11" text-anchor="end">Rwell</text><g data-sym="pnp"><line x1="94" y1="154" x2="108" y2="154" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="108" y1="141" x2="108" y2="167" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="108" y1="149" x2="128" y2="136" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="128" y1="136" x2="128" y2="124" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="108" y1="159" x2="128" y2="172" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="128" y1="172" x2="128" y2="184" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="123.2,143.9 118.8,137.2 115,144.4" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/></g><line x1="128" y1="124" x2="128" y2="86" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="128" cy="86" r="2.6" fill="#1f4fd1"/></g><text x="140" y="150" fill="#1d2943" font-size="11">Q1 (PNP)</text><line x1="128" y1="184" x2="128" y2="222" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="128" y1="222" x2="174" y2="222" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="npn"><line x1="174" y1="222" x2="188" y2="222" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="188" y1="209" x2="188" y2="235" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="188" y1="217" x2="208" y2="204" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="208" y1="204" x2="208" y2="192" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="188" y1="227" x2="208" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="208" y1="240" x2="208" y2="252" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="208,240 200,238 204,232" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/></g><text x="214" y="196" fill="#1d2943" font-size="11">Q2 (NPN)</text><line x1="208" y1="192" x2="208" y2="196" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="208" y1="196" x2="74" y2="196" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="74" y1="196" x2="74" y2="154" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="74" cy="154" r="2.6" fill="#1f4fd1"/></g><line x1="208" y1="252" x2="208" y2="286" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="150" cy="222" r="2.6" fill="#1f4fd1"/></g><line x1="150" y1="222" x2="150" y2="226" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="150" y1="226" x2="150" y2="238" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="150,238 143,241 157,247 143,253 157,259 150,262" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="150" y1="262" x2="150" y2="274" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="150" y1="274" x2="150" y2="286" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="162" y="250" fill="#64748b" font-size="11">Rsub</text><line x1="150" y1="286" x2="208" y2="286" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="180" cy="286" r="2.6" fill="#1f4fd1"/></g><g data-sym="ground"><line x1="180" y1="286" x2="180" y2="300" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="168" y1="300" x2="192" y2="300" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="172" y1="305" x2="188" y2="305" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="176" y1="310" x2="184" y2="310" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="96" y1="222" x2="128" y2="222" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="128" cy="222" r="2.6" fill="#1f4fd1"/></g><polygon points="112,218 112,226 122,222" fill="#b45309" stroke="#b45309" stroke-width="1"/><text x="20" y="214" fill="#b45309" font-size="11">IO pin below GND</text><text x="20" y="246" fill="#b45309" font-size="11">injects into substrate</text><text x="396" y="46" fill="#15803d" font-size="12" text-anchor="middle" font-weight="bold">How to stop it</text><text x="288" y="84" fill="#1d2943" font-size="11">1. Guard rings: P+ to VDD, N+ to GND</text><text x="288" y="106" fill="#1d2943" font-size="11">2. Power up VDD before any IO pin</text><text x="288" y="128" fill="#1d2943" font-size="11">3. Series resistor on the IO pin</text><text x="288" y="150" fill="#1d2943" font-size="11">4. ESD diodes to both rails</text><text x="288" y="172" fill="#1d2943" font-size="11">5. Dense substrate and well taps</text><text x="288" y="220" fill="#b91c1c" font-size="11">Once it fires, only a power cycle</text><text x="288" y="238" fill="#b91c1c" font-size="11">clears it - the current holds it on.</text><text x="10" y="324" fill="#1d2943" font-size="11">p+/n-well/p-sub/n+ is a thyristor: fire it and VDD shorts to GND through the die.</text><text x="10" y="344" fill="#64748b" font-size="11">Rwell and Rsub are the substrate resistances - guard rings and taps make them small.</text></svg></div>$vsq$ as box) n
 where question like $q$%什麼是 Latch-up%$q$;

-- 驗收：七列的 zh / en 都要 t
select left(question, 22) as q,
       answer like '%<svg%' as zh, answer_en like '%<svg%' as en,
       answer_ja like '%<svg%' as ja, answer_ko like '%<svg%' as ko
  from public.interview_questions
 where question like $q$%tr (上升時間) FAIL%$q$
    or question like $q$%什麼是 ESD%$q$
    or question like $q$%Bypass Capacitor（旁路電容）和%$q$
    or question like $q$%PCB 設計中，高速差分對走線%$q$
    or question like $q$%MOSFET 選型時需要關注%$q$
    or question like $q$%什麼是 Latch-up%$q$;
